    'Full-screen cover, selected work, latest writing and a contact call on the homepage; curatorial grid in the portfolio. Gives editors and clients a quick overview.' => 'غلاف بملء الشاشة، وأعمال مختارة، وأحدث الكتابات، ودعوة للتواصل في الصفحة الرئيسية؛ وشبكة تنسيقية في معرض الأعمال. يمنح المحررين والعملاء نظرة سريعة.',
    'Sectioned Showcase' => 'واجهة بأقسام',
    'Cinematic Cover' => 'غلاف سينمائي',
    'Transparent Top Bar' => 'شريط علوي شفاف',
    'Unpublished changes discarded.' => 'تم تجاهل التغييرات غير المنشورة.',
    'No changes to publish.' => 'لا توجد تغييرات للنشر.',
    'Page design published; the rest of the site is unchanged. Use “Revert to previous look” to undo.' => 'تم نشر تصميم الصفحة؛ وبقية الموقع لم تتغير. استخدم "العودة إلى المظهر السابق" للتراجع.',
    '“%s” theme published. Use “Revert to previous look” to undo.' => 'تم نشر قالب "%s". استخدم "العودة إلى المظهر السابق" للتراجع.',
    'Security check failed (CSRF).' => 'فشل التحقق الأمني (CSRF).',
    'Look before applying “%s”' => 'عاين قبل تطبيق "%s"',
    '“%s” applied. Use “Revert to previous look” to undo.' => 'تم تطبيق "%s". استخدم "العودة إلى المظهر السابق" للتراجع.',
    'Reverted to the previous look.' => 'تمت العودة إلى المظهر السابق.',
    'Template options saved.' => 'تم حفظ خيارات القالب.',
    'Click a theme to see what it offers, preview it with your own photographs, customise its colours, logo and menu, and publish.' => 'انقر على قالب لترى ما يقدمه، وعاينه بصورك أنت، وخصّص ألوانه وشعاره وقائمته، ثم انشره.',
    '“%s” is being previewed in your browser only; the site has not changed for visitors.' => 'يُعاين "%s" في متصفحك فقط؛ ولم يتغير الموقع للزوار.',
    '“%s” was applied on %s. If you don’t like it, revert to the previous look in one click.' => 'تم تطبيق "%s" في %s. إن لم يعجبك، عد إلى المظهر السابق بنقرة واحدة.',
    'Revert the site to the look it had before this template?' => 'هل تريد إعادة الموقع إلى المظهر الذي كان عليه قبل هذا القالب؟',
    'Revert' => 'تراجع',
    'Revert to previous look' => 'العودة إلى المظهر السابق',
    'You have unpublished changes' => 'لديك تغييرات غير منشورة',
    '“%s” theme · last edited %s · not visible to visitors yet' => 'قالب "%s" · آخر تعديل %s · غير ظاهر للزوار بعد',
    'Continue editing' => 'متابعة التعديل',
    'Discard the unpublished changes? This cannot be undone.' => 'هل تريد تجاهل التغييرات غير المنشورة؟ لا يمكن التراجع عن ذلك.',
    'Discard changes' => 'تجاهل التغييرات',
    'Your current theme' => 'قالبك الحالي',
    'Customise' => 'تخصيص',
    'Grid' => 'شبكة',
    'Single photo' => 'صورة واحدة',
    'Horizontal' => 'أفقي',
    'Story and list' => 'قصة وقائمة',
    'Filter themes' => 'تصفية القوالب',
    'Open details of the %s theme' => 'فتح تفاصيل قالب %s',
    'Details' => 'التفاصيل',
    'In use' => 'قيد الاستخدام',
    'Preview size' => 'حجم المعاينة',
    'Desktop' => 'سطح المكتب',
    'Unpublished changes' => 'تغييرات غير منشورة',
    'Clear changes' => 'مسح التغييرات',
    'Publish' => 'نشر',
    'Background options' => 'خيارات الخلفية',
    'Open preview in a new tab' => 'فتح المعاينة في علامة تبويب جديدة',
    'The preview on the right uses your own photographs and is shown only to you. Visitors see no change until you press “Publish”.' => 'المعاينة على اليمين تستخدم صورك أنت وتظهر لك وحدك. لا يرى الزوار أي تغيير حتى تضغط "نشر".',
    'Design editor' => 'محرر التصميم',
    'Theme preview' => 'معاينة القالب',
    'Loading preview…' => 'جارٍ تحميل المعاينة…',
    'Apply the changes only to: %s? The rest of the site stays the same. You can revert in one click.' => 'هل تريد تطبيق التغييرات على: %s فقط؟ تبقى بقية الموقع كما هي. يمكنك التراجع بنقرة واحدة.',
    'Publish the changes? Shared settings apply site-wide; page settings apply only to: %s. You can revert in one click.' => 'هل تريد نشر التغييرات؟ الإعدادات المشتركة تسري على الموقع كله؛ وإعدادات الصفحة تسري فقط على: %s. يمكنك التراجع بنقرة واحدة.',
    'Publish the “%s” theme with these settings to the whole site? You can revert in one click.' => 'هل تريد نشر قالب "%s" بهذه الإعدادات على الموقع كله؟ يمكنك التراجع بنقرة واحدة.',
    'Discard all unpublished changes?' => 'هل تريد تجاهل جميع التغييرات غير المنشورة؟',
    'back to details' => 'العودة إلى التفاصيل',
    'Automatic' => 'تلقائي',
    'Upload image' => 'رفع صورة',
    'Uploading…' => 'جارٍ الرفع…',
    'Use default' => 'استخدام الافتراضي',
    'Default image' => 'الصورة الافتراضية',
    'Your image' => 'صورتك',
    'Basic' => 'أساسي',
    'General' => 'عام',
    'Advanced' => 'متقدم',
    'View all' => 'عرض الكل',
    'Every colour on your site, section by section. A colour set here overrides the basic colours.' => 'كل لون في موقعك، قسمًا بقسم. اللون المحدد هنا يتجاوز الألوان الأساسية.',
    'Every text setting on your site, section by section.' => 'كل إعداد للنص في موقعك، قسمًا بقسم.',
    'Change the main colours of your site quickly, in one place.' => 'غيّر الألوان الرئيسية لموقعك بسرعة، من مكان واحد.',
    'Change all the fonts on your site quickly, in one place.' => 'غيّر جميع خطوط موقعك بسرعة، من مكان واحد.',
    'Enter a valid link: https://…, /page/ or mailto:…' => 'أدخل رابطًا صالحًا: https://… أو /page/ أو mailto:…',
    'This tone is too dark. Pick a light tone, or use “Black” for a dark site.' => 'هذه الدرجة داكنة جدًا. اختر درجة فاتحة، أو استخدم "أسود" لموقع داكن.',
    'Which page' => 'أي صفحة',
    'All lists (shared)' => 'جميع القوائم (مشترك)',
    'All project pages (shared)' => 'جميع صفحات المشاريع (مشترك)',
    'own settings' => 'إعدادات خاصة',
    'Settings here apply to every page that has no settings of its own.' => 'الإعدادات هنا تسري على كل صفحة ليس لها إعدادات خاصة.',
    'This page uses the shared settings. To give it its own layout and settings:' => 'هذه الصفحة تستخدم الإعدادات المشتركة. لمنحها تخطيطًا وإعدادات خاصة بها:',
    'Give this page its own settings' => 'امنح هذه الصفحة إعداداتها الخاصة',
    'This page has its own settings; changes to the shared settings do not affect it.' => 'لهذه الصفحة إعداداتها الخاصة؛ والتغييرات في الإعدادات المشتركة لا تؤثر فيها.',
    'Use shared settings' => 'استخدام الإعدادات المشتركة',
    '%s: every project in the list' => '%s: كل مشروع في القائمة',
    'Show all design settings' => 'إظهار جميع إعدادات التصميم',
    'Colours, fonts, menu and other pages' => 'الألوان والخطوط والقائمة والصفحات الأخرى',
    'The change could not be saved. Check your connection and try again.' => 'تعذّر حفظ التغيير. تحقق من اتصالك وحاول مجددًا.',
    'Languages' => 'اللغات',
    'Languages section' => 'قسم اللغات',
    'Languages & Panel Language' => 'اللغات ولغة اللوحة',
    'Translation Table' => 'جدول الترجمة',
    'Remove %s (%s) from the site? Visitors can no longer choose this language.' => 'هل تريد إزالة %s (%s) من الموقع؟ لن يتمكن الزوار من اختيار هذه اللغة بعد الآن.',
    'Page names and URL slugs for this language are managed in' => 'أسماء الصفحات وروابطها لهذه اللغة تُدار من',
    'Settings › URL Management' => 'الإعدادات › إدارة الروابط',
    '.' => '.',
    'Security check failed (CSRF). Reload the page and try again.' => 'فشل التحقق الأمني (CSRF). أعد تحميل الصفحة وحاول مجددًا.',
    'Contact page texts saved.' => 'تم حفظ نصوص صفحة التواصل.',
    'Kicker' => 'العنوان التمهيدي',
    'Response note' => 'ملاحظة الرد',
    'Contact Page' => 'صفحة التواصل',
    'The texts visitors read on the contact page. Layout and look are in Design.' => 'النصوص التي يقرؤها الزوار في صفحة التواصل. التخطيط والمظهر في قسم التصميم.',
    'The contact page is currently off; texts are saved but not shown on the site.' => 'صفحة التواصل متوقفة حاليًا؛ النصوص تُحفظ لكنها لا تُعرض في الموقع.',
    'Email' => 'البريد الإلكتروني',
    'Shown on the page; form notifications also go here. Phone is in Design › Contact.' => 'يظهر في الصفحة؛ وإليه تُرسل إشعارات النموذج أيضًا. الهاتف في التصميم › التواصل.',
    'Logo' => 'الشعار',
    'Pages & Features' => 'الصفحات والميزات',
    'URL Management' => 'إدارة الروابط',
    'Privacy' => 'الخصوصية',
    'Integrations' => 'التكاملات',
    'Account & Backup' => 'الحساب والنسخ الاحتياطي',
    'Site-wide settings. Use “Themes” for page layouts and the Content section in the sidebar for content.' => 'إعدادات على مستوى الموقع. استخدم "القوالب" لتخطيطات الصفحات وقسم المحتوى في الشريط الجانبي للمحتوى.',
    'Settings sections' => 'أقسام الإعدادات',
    'Show source language alongside' => 'إظهار اللغة المصدر بجانبها',
    'Copy empty fields from %s' => 'نسخ الحقول الفارغة من %s',
    'Auto-translate empty fields (%s → %s)' => 'ترجمة الحقول الفارغة تلقائيًا (%s → %s)',
    'Translating…' => 'جارٍ الترجمة…',
    '%d fields filled. Remember to save.' => 'تم ملء %d حقلًا. لا تنسَ الحفظ.',
    'No empty fields to fill.' => 'لا توجد حقول فارغة لملئها.',
    'The translation service could not be reached. Try again shortly.' => 'تعذّر الوصول إلى خدمة الترجمة. حاول مجددًا بعد قليل.',
    'The source language is selected.' => 'اللغة المصدر محددة.',
    'All fields filled' => 'جميع الحقول مملوءة',
    '%d of %d fields filled' => 'تم ملء %d من %d حقلًا',
    'Editing language' => 'لغة التحرير',
    'Source' => 'المصدر',
    'Content language' => 'لغة المحتوى',
    'No %s translation' => 'لا توجد ترجمة %s',
    '%s: %d of %d fields filled' => '%s: تم ملء %d من %d حقلًا',
    'Translation' => 'الترجمة',
    'Missing %s' => 'الناقص: %s',
    'Panel' => 'اللوحة',
    'Visitors' => 'الزوار',
    'Design' => 'التصميم',
    'CONTENT' => 'المحتوى',
    'VISITORS' => 'الزوار',
    'DESIGN' => 'التصميم',
    'SETTINGS' => 'الإعدادات',
    'Panel language' => 'لغة اللوحة',
    'Changes only the panel’s menus and buttons. Content language is chosen from the bar at the top of each editor.' => 'يغيّر قوائم اللوحة وأزرارها فقط. لغة المحتوى تُختار من الشريط أعلى كل محرر.',
    'Privacy & KVKK Settings' => 'إعدادات الخصوصية و KVKK',
    'Section pages' => 'صفحات الأقسام',
    '13. Sidebar List' => '13. قائمة الشريط الجانبي',
    'Numbered project list on the left, one large uncropped photo on the right; hovering the list switches the photo. Best for a few strong projects.' => 'قائمة مشاريع مرقمة يسارًا، وصورة كبيرة غير مقصوصة يمينًا؛ والمرور على القائمة يبدّل الصورة. الأنسب لعدد قليل من المشاريع القوية.',
    '14. Archive by Year' => '14. أرشيف بحسب السنة',
    'Projects grouped under year headings with thumbnail, title and place. Best for a long, multi-project archive.' => 'مشاريع مجمّعة تحت عناوين السنوات مع مصغّرة وعنوان ومكان. الأنسب لأرشيف طويل كثير المشاريع.',
    '15. Contact Sheet' => '15. ورقة التلامس',
    'All works as small numbered frames on black, like a film contact sheet; frames enlarge on hover. Best for many works.' => 'جميع الأعمال كلقطات صغيرة مرقمة على خلفية سوداء، مثل ورقة تلامس الفيلم؛ وتكبر اللقطات عند المرور عليها. الأنسب للأعمال الكثيرة.',
    '16. Photo + Statement' => '16. صورة + نص',
    'One large photo on one side, a short statement in large type and the project list on the other. The text comes from the site description in Site Settings › General.' => 'صورة كبيرة في جانب، ونص قصير بخط كبير وقائمة المشاريع في الجانب الآخر. النص مأخوذ من وصف الموقع في إعدادات الموقع › عام.',
    '17. Project Map' => '17. خريطة المشاريع',
    'Each project as a point on a world map where it was shot; clicking shows the cover and link. Project list alongside. Places are found from each project’s Location field.' => 'كل مشروع نقطة على خريطة العالم في مكان تصويره؛ والنقر يعرض الغلاف والرابط. وقائمة المشاريع بجانبها. تُحدَّد الأماكن من حقل الموقع في كل مشروع.',
    '18. Sectioned Showcase' => '18. واجهة بأقسام',
    'Full-screen cover, then Selected Work cards, latest blog posts (if blog is on), a short intro and About / Contact links. Everything on one page.' => 'غلاف بملء الشاشة، ثم بطاقات الأعمال المختارة، وأحدث منشورات المدونة (إن كانت مفعّلة)، ومقدمة قصيرة، وروابط نبذة / تواصل. كل شيء في صفحة واحدة.',
    '20. Thumbnail Grid' => '20. شبكة المصغّرات',
    'All work as small thumbnails side by side; titles on hover. Looks best with the sidebar menu. Columns and cropping are chosen on the Templates page.' => 'جميع الأعمال كمصغّرات متجاورة؛ والعناوين عند المرور. تبدو أفضل مع القائمة الجانبية. تُختار الأعمدة والقص من صفحة القوالب.',
    '21. Photobook Spreads' => '21. صفحات كتاب مصوّر متقابلة',
    'Work laid out as two-page book spreads on warm paper; the first page shows the site name and description. Page by page on phones.' => 'أعمال مرتبة كصفحتين متقابلتين من كتاب على ورق دافئ؛ والصفحة الأولى تعرض اسم الموقع ووصفه. صفحة بصفحة على الهواتف.',
    '22. Mosaic Wall' => '22. جدار الفسيفساء',
    'Covers of varying sizes form a dense wall; titles on hover. Columns are chosen on the Templates page.' => 'أغلفة بأحجام متفاوتة تشكّل جدارًا كثيفًا؛ والعناوين عند المرور. تُختار الأعمدة من صفحة القوالب.',
    '23. Photo Wall' => '23. جدار الصور',
    'Photos stacked uncropped in columns at their natural proportions, titles below. Set the column count in Themes › Customise › Homepage. Best for: series that mix portrait and landscape photos.' => 'صور مرصوصة بلا قص في أعمدة بنسبها الطبيعية، والعناوين تحتها. حدّد عدد الأعمدة من القوالب › تخصيص › الصفحة الرئيسية. الأنسب لـ: السلاسل التي تجمع صورًا طولية وعرضية.',
    '24. Staggered Gallery' => '24. معرض متدرّج',
    'Uncropped photos in varying widths and offsets with generous space. Best for: calm selections that should feel like a gallery wall.' => 'صور غير مقصوصة بعروض وإزاحات متفاوتة مع فراغ سخي. الأنسب لـ: المختارات الهادئة التي ينبغي أن تبدو كجدار معرض.',
    '25. One Large, Two Small' => '25. واحدة كبيرة واثنتان صغيرتان',
    'Blocks of three: one large and two small photos, the large one alternating sides. Best for: projects with strong cover photos.' => 'مجموعات من ثلاث: صورة كبيرة واثنتان صغيرتان، والكبيرة تتبادل الجانبين. الأنسب لـ: المشاريع ذات صور الغلاف القوية.',
    '26. Featured + Grid' => '26. مميز + شبكة',
    'The first work large and uncropped, then small square thumbnails. Best for: when you want to lead with one recent work.' => 'العمل الأول كبيرًا وغير مقصوص، ثم مصغّرات مربعة صغيرة. الأنسب لـ: حين تريد أن تتصدر بعمل حديث واحد.',
    '27. Zigzag Stream' => '27. تدفق متعرّج',
    'Uncropped photos flow down the page, alternating left and right, titles below. Best for: strong single frames worth a long look.' => 'صور غير مقصوصة تنساب نزولًا في الصفحة، متناوبة يسارًا ويمينًا، والعناوين تحتها. الأنسب لـ: اللقطات المنفردة القوية الجديرة بنظرة طويلة.',
    '28. Split Screens' => '28. شاشات مقسومة',
    'Each project fills a screen: photo on one half, title and short text on the other, sides alternating. Choose edge-to-edge or framed (magazine) style.' => 'كل مشروع يملأ شاشة: صورة في نصف، وعنوان ونص قصير في النصف الآخر، مع تبادل الجانبين. اختر النمط الممتد من الحافة إلى الحافة أو المؤطَّر (مجلة).',
    '29. Three Panels' => '29. ثلاث لوحات',
    'The screen splits into three tall panels, each a project cover with its name centred. Stacked on phones. Best for: portfolios with three to six main projects.' => 'تنقسم الشاشة إلى ثلاث لوحات طويلة، كل منها غلاف مشروع واسمه في الوسط. تتراص فوق بعضها على الهواتف. الأنسب لـ: معارض الأعمال التي تضم ثلاثة إلى ستة مشاريع رئيسية.',
    '30. Section Banners' => '30. لافتات الأقسام',
    'Each menu section becomes a wide banner with a cover photo, large title and an arrow. Shows sections on the homepage and projects on project lists.' => 'يصبح كل قسم من القائمة لافتة عريضة فيها صورة غلاف وعنوان كبير وسهم. تعرض الأقسام في الصفحة الرئيسية والمشاريع في قوائم المشاريع.',
    '31. Light Table' => '31. طاولة الضوء',
    'One large photo with a vertical thumbnail strip on the right; click a thumbnail (or use the arrow keys) to change the photo. On phones the strip moves below. Best for: showing photos one at a time on a dark background.' => 'صورة كبيرة مع شريط مصغّرات عمودي على اليمين؛ انقر على مصغّرة (أو استخدم مفاتيح الأسهم) لتغيير الصورة. على الهواتف ينتقل الشريط إلى الأسفل. الأنسب لـ: عرض الصور واحدة تلو الأخرى على خلفية داكنة.',
    '19. Free Collage' => '19. كولاج حر',
    'Photos placed freely in varied sizes and positions without a grid; titles appear on hover. Single column on phones. For artistic and personal work.' => 'صور موضوعة بحرية بأحجام ومواضع متنوعة بلا شبكة؛ وتظهر العناوين عند المرور. عمود واحد على الهواتف. للأعمال الفنية والشخصية.',
    'You have unsaved changes' => 'لديك تغييرات غير محفوظة',
    'Discard' => 'تجاهل',
    'Unlisted' => 'غير مدرج',
    'View on site' => 'عرض في الموقع',
    'Save (Ctrl+S)' => 'حفظ (Ctrl+S)',
    'Homepage slide' => 'شريحة الصفحة الرئيسية',
    'Site settings / design' => 'إعدادات الموقع / التصميم',
    'CSRF security verification failed.' => 'فشل التحقق الأمني CSRF.',
    'All page names, URL slugs, and top menu links have been updated.' => 'تم تحديث جميع أسماء الصفحات وروابطها وروابط القائمة العلوية.',
    'Customize page names and permalinks. Changes automatically sync across panel templates, sidebars, and public navigation.' => 'خصّص أسماء الصفحات والروابط الدائمة. تتزامن التغييرات تلقائيًا في قوالب اللوحة والأشرطة الجانبية والتنقل العام.',
